(function($){
    'use strict';

    function setBusy($btn, busy, label) {
        if (!$btn || !$btn.length) return;
        if (busy) {
            $btn.addClass('is-busy').prop('disabled', true);
            if (label) $btn.data('orig-label', $btn.text()).text(label);
        } else {
            $btn.removeClass('is-busy').prop('disabled', false);
            if ($btn.data('orig-label')) {
                $btn.text($btn.data('orig-label'));
                $btn.removeData('orig-label');
            }
        }
    }

    const ACTIONS = {
        PRUNE: 'contactinbox_gdpr_prune_logs',
        CLEAR: 'contactinbox_gdpr_clear_logs',
        EXPORT_INFO: 'contactinbox_gdpr_export_info',
        DOWNLOAD_CSV: 'contactinbox_download_gdpr_csv',
        DELETE_FROM_CRM: 'ci_gdpr_delete_from_crm'
    };

    function payload(extra) {
        return Object.assign({ nonce: ContactINGDPRLog.nonce }, extra || {});
    }

    function assertEnv() {
        if (!window.ContactINGDPRLog || !ContactINGDPRLog.ajax_url || !ContactINGDPRLog.nonce) {
            console.error('[ContactIN] Missing GDPR log script data');
            return false;
        }
        return true;
    }

    // --- Auto-submit filters on change --------------------------------------
    $('#crm-status-filter, #status-filter-gdpr, #gdpr-log-per-page').on('change', function() {
        $('#contactin-gdpr-log-form').submit();
    });

    // --- Prune Old Logs with Synced Contact Warning ---------------------------
    $('#contactin-prune-gdpr-btn').on('click', function(e){
        e.preventDefault();
        if (!assertEnv()) return;

        const days = ContactINGDPRLog.retention_days || 90;
        
        // Fetch synced count for analysis
        $.post(ContactINGDPRLog.ajax_url, payload({ action: 'contactinbox_gdpr_get_synced_count' }))
            .done(res => {
                const syncedCount = res.data?.synced_count || 0;
                
                // Show analytical warning modal
                showPruneWarningModal(days, syncedCount, () => {
                    const $btn = $('#contactin-prune-gdpr-btn');
                    setBusy($btn, true, ContactINGDPRLog.i18n?.pruning || 'Pruning...');

                    $.post(ContactINGDPRLog.ajax_url, payload({ action: ACTIONS.PRUNE }))
                        .done(res => {
                            if (res.success) {
                                cinShowMessage(res.data?.message || 'Logs pruned successfully.', 'success');
                                setTimeout(() => location.reload(), 1500);
                            } else {
                                cinShowMessage(res.data?.message || 'Failed to prune logs.', 'error');
                                setBusy($btn, false);
                            }
                        })
                        .fail(err => {
                            console.error('[ContactIN] Network/prune error:', err);
                            cinShowMessage(ContactINGDPRLog.i18n?.network_error || 'Network error.', 'error');
                            setBusy($btn, false);
                        });
                });
            })
            .fail(err => {
                console.error('[ContactIN] Failed to fetch synced count:', err);
                cinShowMessage(ContactINGDPRLog.i18n?.network_error || 'Network error.', 'error');
            });
    });

    // --- Clear All Logs with Synced Contact Warning ---------------------------
    $('#contactin-clear-gdpr-logs').on('click', function(e){
        e.preventDefault();
        if (!assertEnv()) return;

        // Fetch synced count for analysis
        $.post(ContactINGDPRLog.ajax_url, payload({ action: 'contactinbox_gdpr_get_synced_count' }))
            .done(res => {
                const syncedCount = res.data?.synced_count || 0;
                
                // Show analytical warning modal
                showClearWarningModal(syncedCount, () => {
                    const $btn = $('#contactin-clear-gdpr-logs');
                    setBusy($btn, true, ContactINGDPRLog.i18n?.clearing || 'Clearing...');

                    $.post(ContactINGDPRLog.ajax_url, payload({ action: ACTIONS.CLEAR }))
                        .done(res => {
                            if (res.success) {
                                cinShowMessage(res.data?.message || 'All logs cleared successfully.', 'success');
                                setTimeout(() => location.reload(), 1500);
                            } else {
                                cinShowMessage(res.data?.message || 'Failed to clear logs.', 'error');
                                setBusy($btn, false);
                            }
                        })
                        .fail(err => {
                            console.error('[ContactIN] Network/clear error:', err);
                            cinShowMessage(ContactINGDPRLog.i18n?.network_error || 'Network error.', 'error');
                            setBusy($btn, false);
                        });
                });
            })
            .fail(err => {
                console.error('[ContactIN] Failed to fetch synced count:', err);
                cinShowMessage(ContactINGDPRLog.i18n?.network_error || 'Network error.', 'error');
            });
    });

    // --- Export CSV - Modern Implementation ----------------------------------
    $('.cin-download-csv').on('click', function(e){
        e.preventDefault();
        if (!assertEnv()) return;

        const $btn = $(this);
        const nonce = ContactINGDPRLog.nonce;
        const search = ContactINGDPRLog.search || '';
        const crmStatus = ContactINGDPRLog.crm_status || 'all';
        const deletionStatus = ContactINGDPRLog.deletion_status || 'all';

        if (!nonce) {
            cinShowMessage('Missing security token.', 'error');
            return;
        }

        // Build base URL with all filters
        const baseUrl = ContactINGDPRLog.ajax_url + 
            '?action=' + ACTIONS.DOWNLOAD_CSV +
            '&_wpnonce=' + encodeURIComponent(nonce) +
            '&s=' + encodeURIComponent(search) +
            '&crm_status=' + encodeURIComponent(crmStatus) +
            '&deletion_status=' + encodeURIComponent(deletionStatus);

        // Use modern export helper if available
        if (typeof window.cinExportHelper === 'function') {
            window.cinExportHelper({
                infoAction: ACTIONS.EXPORT_INFO,
                baseUrl: baseUrl,
                search: search,
                crm_status: crmStatus,
                deletion_status: deletionStatus,
                nonce: nonce,
                ajax_url: ContactINGDPRLog.ajax_url,
                gdpr_mode: true  // Flag to indicate GDPR-specific handling
            });
        } else {
            // Fallback to legacy implementation
            $.post(ContactINGDPRLog.ajax_url, payload({ action: ACTIONS.EXPORT_INFO }))
                .done(res => {
                    if (res.success) {
                        const data = res.data;
                        const rawChunk = parseInt($('#cin-export-chunk').val(), 10);
                        const limit = Math.min(Math.max(isNaN(rawChunk) ? data.limit : rawChunk, 1), data.limit);
                        const batches = Math.ceil(data.total / limit) || 1;

                        $('#cin-export-total').text(data.total);
                        $('#cin-export-max').text(limit);
                        $('#cin-export-modal').addClass('active');
                        downloadGdprExportBatch(0, batches, limit);
                    } else {
                        cinShowMessage(res.data?.message || 'Failed to get export info.', 'error');
                    }
                })
                .fail(err => {
                    console.error('[ContactIN] Network/export-info error:', err);
                    cinShowMessage(ContactINGDPRLog.i18n?.network_error || 'Network error.', 'error');
                });
        }
    });

    // --- Export Modal Close --------------------------------------------------
    $('#cin-export-close').on('click', function() {
        $('#cin-export-modal').removeClass('active');
        $('#cin-export-links').empty();
    });

    // --- Download Export Batch -----------------------------------------------
    function downloadGdprExportBatch(batch, total_batches, limit) {
        $.post(ContactINGDPRLog.ajax_url, payload({
            action: ACTIONS.DOWNLOAD_CSV,
            batch: batch,
            limit: limit
        }))
            .done(res => {
                if (res.success && res.data) {
                    const csvContent = 'data:text/csv;charset=utf-8,' + encodeURIComponent(convertArrayToCSV(res.data.csv_data));
                    const link = $('<a>')
                        .addClass('cin-export-link')
                        .attr('href', csvContent)
                        .attr('download', res.data.filename)
                        .text(res.data.filename);
                    $('#cin-export-links').append(link).append('<br />');

                    if (batch + 1 < total_batches) {
                        downloadGdprExportBatch(batch + 1, total_batches, limit);
                    }
                } else {
                    cinShowMessage(res.data?.message || 'Failed to export batch.', 'error');
                }
            })
            .fail(err => {
                console.error('[ContactIN] Network/export-batch error:', err);
                cinShowMessage(ContactINGDPRLog.i18n?.network_error || 'Network error.', 'error');
            });
    }

    // --- Delete from CRM -----------------------------------------------------
    $('.cin-delete-from-crm-btn').on('click', function(e){
        e.preventDefault();
        if (!assertEnv()) return;

        const msg = ContactINGDPRLog.i18n?.confirmDeleteCrm
            || 'Delete these contacts from the CRM? This action cannot be undone.';
        if (!confirm(msg)) return;

        const $btn = $(this);
        setBusy($btn, true, ContactINGDPRLog.i18n?.deleting || 'Deleting...');

        $.post(ContactINGDPRLog.ajax_url, payload({
            action: ACTIONS.DELETE_FROM_CRM,
            nonce: $btn.data('nonce')
        }))
            .done(res => {
                if (res.success) {
                    cinShowMessage(res.data?.message || 'Deleted from CRM successfully.', 'success');
                    setTimeout(() => location.reload(), 1500);
                } else {
                    cinShowMessage(res.data?.message || 'Failed to delete from CRM.', 'error');
                    setBusy($btn, false);
                }
            })
            .fail(err => {
                console.error('[ContactIN] Network/delete-crm error:', err);
                cinShowMessage(ContactINGDPRLog.i18n?.network_error || 'Network error.', 'error');
                setBusy($btn, false);
            });
    });

    // --- Warning Modals for Prune & Clear Operations --------------------------
    function showPruneWarningModal(days, syncedCount, onConfirm) {
        const html = `
            <div id="cin-prune-warning-modal" class="cin-modal-overlay" role="dialog" aria-modal="true" aria-labelledby="cin-prune-modal-title">
                <div class="cin-confirm-modal">
                    <h3 id="cin-prune-modal-title">⚠️ Prune Old Logs - GDPR Compliance Notice</h3>
                    <div class="cin-modal-analytics">
                        <p class="cin-modal-notice">
                            This action will delete all GDPR deletion logs <strong>older than ${days} days</strong>.
                        </p>
                        <div class="cin-modal-analysis">
                            <h4>Impact Analysis</h4>
                            ${syncedCount > 0 ? `
                            <div class="cin-analysis-item">
                                <span class="cin-analysis-label">CRM-Synced Contacts:</span>
                                <span class="cin-analysis-value" style="color: #d32f2f; font-weight: bold;">${syncedCount}</span>
                            </div>
                            <div class="cin-analysis-warning" style="background-color: #fff3cd; border: 1px solid #ffc107; border-radius: 4px; padding: 12px; margin-top: 8px;">
                                <p style="margin: 0; color: #856404; font-size: 13px;">
                                    <strong>⚠️ CRM Sync Gap:</strong> Deleting these logs removes your local audit trail, but <strong>${syncedCount} CRM-synced contact record(s) will NOT be deleted from your CRM system</strong>. You must delete them separately in your CRM to maintain full GDPR compliance.
                                </p>
                            </div>
                            ` : `
                            <div class="cin-analysis-item">
                                <span class="cin-analysis-label" style="color: #999;">No CRM-synced contacts</span>
                            </div>
                            `}
                        </div>
                    </div>
                    <div class="cin-modal-footer">
                        <button type="button" class="button" id="cin-prune-cancel">Cancel</button>
                        <button type="button" class="button button-primary" id="cin-prune-confirm">Continue with Prune</button>
                    </div>
                </div>
            </div>
        `;
        
        const $modal = $(html);
        $('body').append($modal);
        $modal.addClass('active');
        
        $modal.find('#cin-prune-cancel').on('click', () => $modal.remove());
        $modal.find('#cin-prune-confirm').on('click', () => {
            $modal.remove();
            onConfirm();
        });
        
        // Close on backdrop click
        $modal.on('click', function(e) {
            if ($(e.target).is('#cin-prune-warning-modal')) {
                $modal.remove();
            }
        });
    }

    function showClearWarningModal(syncedCount, onConfirm) {
        const html = `
            <div id="cin-clear-warning-modal" class="cin-modal-overlay" role="dialog" aria-modal="true" aria-labelledby="cin-clear-modal-title">
                <div class="cin-confirm-modal">
                    <h3 id="cin-clear-modal-title">⚠️ Clear All Logs - GDPR Compliance Notice</h3>
                    <div class="cin-modal-analytics">
                        <p class="cin-modal-notice">
                            This action will <strong>permanently delete ALL GDPR deletion logs</strong>. This cannot be undone.
                        </p>
                        <div class="cin-modal-analysis">
                            <h4>Impact Analysis</h4>
                            ${syncedCount > 0 ? `
                            <div class="cin-analysis-item">
                                <span class="cin-analysis-label">CRM-Synced Contacts:</span>
                                <span class="cin-analysis-value" style="color: #d32f2f; font-weight: bold;">${syncedCount}</span>
                            </div>
                            <div class="cin-analysis-warning" style="background-color: #ffebee; border: 1px solid #e57373; border-radius: 4px; padding: 12px; margin-top: 8px;">
                                <p style="margin: 0; color: #c62828; font-size: 13px; font-weight: 500;">
                                    🔴 <strong>Critical GDPR Gap:</strong> You have <strong>${syncedCount} CRM-synced contact deletion(s)</strong> in your logs. Clearing these logs will:
                                </p>
                                <ul style="margin: 8px 0 0 0; padding-left: 20px; color: #c62828; font-size: 13px;">
                                    <li>Remove your local audit trail for these deletions</li>
                                    <li><strong>NOT delete these contacts from your CRM system</strong></li>
                                    <li>Create a compliance gap if audited by data protection authorities</li>
                                </ul>
                                <p style="margin: 8px 0 0 0; color: #c62828; font-size: 13px;">
                                    <strong>Recommended:</strong> Use the Maintenance page to delete synced contacts from your CRM first.
                                </p>
                            </div>
                            ` : `
                            <div class="cin-analysis-item">
                                <span class="cin-analysis-label" style="color: #999;">No CRM-synced contacts</span>
                            </div>
                            `}
                        </div>
                    </div>
                    <div class="cin-modal-footer">
                        <button type="button" class="button" id="cin-clear-cancel">Cancel</button>
                        <button type="button" class="button button-primary" style="background-color: #d32f2f; border-color: #d32f2f;" id="cin-clear-confirm">Delete All Logs</button>
                    </div>
                </div>
            </div>
        `;
        
        const $modal = $(html);
        $('body').append($modal);
        $modal.addClass('active');
        
        $modal.find('#cin-clear-cancel').on('click', () => $modal.remove());
        $modal.find('#cin-clear-confirm').on('click', () => {
            $modal.remove();
            onConfirm();
        });
        
        // Close on backdrop click
        $modal.on('click', function(e) {
            if ($(e.target).is('#cin-clear-warning-modal')) {
                $modal.remove();
            }
        });
    }

    // --- Convert Array to CSV ------------------------------------------------
    function convertArrayToCSV(array) {
        return array.map(row => row.map(cell => {
            if (cell === null || cell === undefined) return '';
            if (typeof cell === 'string' && (cell.includes(',') || cell.includes('"') || cell.includes('\n'))) {
                return '"' + cell.replace(/"/g, '""') + '"';
            }
            return cell;
        }).join(',')).join('\n');
    }

    // --- Utility: Show Message -----------------------------------------------
    function cinShowMessage(msg, type) {
        if (typeof window.cinShowMessage === 'function') {
            window.cinShowMessage(msg, type === 'error' ? 'error' : 'success');
            return;
        }
        // Fallback
        alert(msg);
    }

})(jQuery);
